import { useEffect, useState } from "react";

type Product = { id: string; name: string };
type ProductListProps = { products: Product[]; query: string };

export function ProductList({ products, query }: ProductListProps) {
  const [visible, setVisible] = useState<Product[]>([]);

  useEffect(() => {
    setVisible(products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase())));
  }, [query]);

  return (
    <ul>
      {visible.map((p, i) => (
        <li key={i}>{p.name}</li>
      ))}
    </ul>
  );
}

